const pages=[...document.querySelectorAll('.section')],nav=[...document.querySelectorAll('[data-page]')];function go(id){pages.forEach(x=>x.classList.toggle('active',x.id===id));nav.forEach(x=>x.classList.toggle('active',x.dataset.page===id));location.hash=id;scrollTo(0,0);if(id==='personas')loadPersonas();if(id==='import')loadSources()}nav.forEach(x=>x.onclick=()=>go(x.dataset.page));
const seedPersonas=[{id:'jordan',name:'Jordan Lee',title:'VP Sales Operations',seniority:'VP',industry:'B2B software',difficulty:'Core',source:'Transcript-backed',status:'published'},{id:'priya',name:'Priya Shah',title:'Chief Financial Officer',seniority:'C-suite',industry:'Professional services',difficulty:'Executive',source:'Manager-built',status:'published'},{id:'marcus',name:'Marcus Reed',title:'Director of RevOps',seniority:'Director',industry:'SaaS',difficulty:'Advanced',source:'Transcript-backed',status:'draft'}];
function initials(name){return name.split(' ').map(x=>x[0]).join('').slice(0,2)}function personaCard(p){return '<article class="panel persona-card"><div style="display:flex;justify-content:space-between"><span class="pill">'+p.source+'</span><span class="tag '+(p.status==='published'?'green':'')+'">'+p.status+'</span></div><div class="person">'+initials(p.name)+'</div><h2 style="margin-bottom:3px">'+p.name+'</h2><p class="sub" style="margin:0">'+p.title+'</p><div class="meta"><div><span>Industry</span>'+p.industry+'</div><div><span>Highest level</span>'+p.difficulty+'</div></div></article>'}async function loadPersonas(){let data=seedPersonas;try{const r=await fetch('/api/personas');if(r.ok)data=await r.json()}catch{}document.querySelector('#personaGrid').innerHTML=data.map(personaCard).join('');document.querySelector('#personaCount').textContent=data.length+' buyers'}
document.querySelector('#personaForm').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget));const msg=document.querySelector('#personaMessage');try{const r=await fetch('/api/personas',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(data)});if(!r.ok)throw 0;msg.textContent='Persona saved as a reviewable draft. Add pains, objections, decision process, and behavioral anchors before publishing.'}catch{msg.textContent='Demo draft created. Persistent storage will activate when the workspace database is available.'}msg.classList.remove('hidden');e.currentTarget.reset();setTimeout(()=>go('personas'),800)};
